150	// FAST PATH 1: prefill, head_dim=128, bf16 (paged+non-paged, pack-GQA, varlen, causal/non-causal)
151	//
152	// Reuses the validated hd128 wgmma+softmax consumer mainloop from fused_attn.cu (1 producer + 2
153	// consumer warpgroups, 128x128 tile, 3-stage K/V ring, intra-WG QK||PV overlap), but replaces the
154	// whole-tensor TMA load path with a cp.async GATHER that swizzle-stores packed-Q and paged/contig
155	// K/V into the SAME 128B-swizzle smem layout the descriptors expect (tma_swz_test{,_v}.cu proved
156	// this layout reproduces TMA byte-for-byte). Epilogue scatters O/LSE via the pack-GQA divmod.
157	// ======================================================================================
158	namespace pf {
159	// PF_CPASYNC=1: pipelined cp.async gather loaders (fast path). =0: synchronous uint4 stores (debug).
160	#ifndef PF_CPASYNC
161	#define PF_CPASYNC 1
162	#endif
163	constexpr int CTA_M = 128, CTA_N = 128, HD = 128, WG = 128;
164	constexpr int NThreads = 3 * WG, NumCons = 2 * WG, NumProd = WG, WS_STAGES = 3;
165	constexpr int KVSTRIDE = CTA_N * HD;            // one swizzled K/V tile (elems)
166	
167	// ---- 128B swizzle (validated) ----
168	// 128B-swizzle of a [.,HD] K-major bf16 tile, byte-exact with cp.async.bulk.tensor (TMA): the column's
169	// bits 3-5 are XORed by the row phase (row&7). Verified against the TMA-landed layout (tma_probe.cu).
170	__device__ __forceinline__ int koff(int row, int c) { return (c >> 6) * 8192 + row * 64 + ((c & 63) ^ ((row & 7) << 3)); } // K-major (Q,K)
171	__device__ __forceinline__ int voff(int key, int dv) { return (dv >> 6) * 8192 + key * 64 + ((dv & 63) ^ ((key & 7) << 3)); } // MN-major (V)
172	// Row-count-generic swizzle: the [64-col] block stride is ROWS*64 (the # rows in the tile: CTA_M for
173	// Q, CN for K/V). ROWS=128 reproduces koff/voff exactly (8192 = 128*64).
174	template <int ROWS> __device__ __forceinline__ int koffR(int row, int c) { return (c >> 6) * (ROWS * 64) + row * 64 + ((c & 63) ^ ((row & 7) << 3)); }
175	template <int ROWS> __device__ __forceinline__ int voffR(int key, int dv) { return (dv >> 6) * (ROWS * 64) + key * 64 + ((dv & 63) ^ ((key & 7) << 3)); }
176	// Descriptor col-block step (16-byte units) for a ROWS-row tile: within a 64-col block step 16 cols
177	// (=2 units); crossing to the next 64-col block jumps ROWS*64 elems = ROWS*8 units. ROWS=128 -> 1024.
178	template <int ROWS> __device__ __forceinline__ uint64_t qk_doffR(int kb) { return (uint64_t)((kb & 3) * 2 + (kb >> 2) * (ROWS * 8)); }
