180	__device__ __forceinline__ uint64_t make_smem_desc(uint32_t a, uint32_t lbo, uint32_t sbo, uint32_t lt) {
181	    uint64_t d = 0;
182	    d |= (uint64_t)((a >> 4) & 0x3FFFu);
183	    d |= (uint64_t)((lbo >> 4) & 0x3FFFu) << 16;
184	    d |= (uint64_t)((sbo >> 4) & 0x3FFFu) << 32;
185	    d |= (uint64_t)(lt & 0x3u) << 62;
186	    return d;
187	}
