231	template <int CN = CTA_N>
232	__device__ __forceinline__ float softmax_stats(float (&s)[CN/2], float* m_r, float* l_r, int r, int nb, float s2) {
233	    float b0 = -INFINITY, b1 = -INFINITY, b2 = -INFINITY, b3 = -INFINITY;
234	#pragma unroll
235	    for (int c = 0; c < CN / 8; c += 2) {
236	        b0 = fmaxf(b0, s[c*4+r*2+0]);     b1 = fmaxf(b1, s[c*4+r*2+1]);
237	        b2 = fmaxf(b2, s[(c+1)*4+r*2+0]); b3 = fmaxf(b3, s[(c+1)*4+r*2+1]);
238	    }
239	    float bm = fmaxf(fmaxf(b0, b1), fmaxf(b2, b3));
240	    bm = quad_max(bm);
241	    float scale_f;
242	    if (nb == 0) { m_r[r] = bm; scale_f = 1.f; }
243	    else { float prev = m_r[r]; m_r[r] = fmaxf(m_r[r], bm);
244	           float cur = (m_r[r] == -INFINITY) ? 0.f : m_r[r];
245	           scale_f = ex2_approx((prev - cur) * s2); l_r[r] *= scale_f; }
246	    float max_scaled = (m_r[r] == -INFINITY) ? 0.f : m_r[r] * s2;
247	    float ls0 = 0.f, ls1 = 0.f, ls2 = 0.f, ls3 = 0.f;
248	#pragma unroll
249	    for (int c = 0; c < CN / 8; c += 2) {
250	        float p0 = ex2_approx(s[c*4+r*2+0]     * s2 - max_scaled);
251	        float p1 = ex2_approx(s[c*4+r*2+1]     * s2 - max_scaled);
252	        float p2 = ex2_approx(s[(c+1)*4+r*2+0] * s2 - max_scaled);
253	        float p3 = ex2_approx(s[(c+1)*4+r*2+1] * s2 - max_scaled);
254	        s[c*4+r*2+0] = p0;     s[c*4+r*2+1] = p1;
255	        s[(c+1)*4+r*2+0] = p2; s[(c+1)*4+r*2+1] = p3;
256	        ls0 += p0; ls1 += p1; ls2 += p2; ls3 += p3;
257	    }
258	    float lsum = (ls0 + ls1) + (ls2 + ls3);
259	    l_r[r] = (nb == 0) ? lsum : l_r[r] + lsum;
260	    return scale_f;
261	}
262	// Combined causal + key-length mask. r=0->qlo (row_lo), r=1->qhi (row_hi). col indices: s[c*4+r*2+p].
263	// Cheap causal/bounds-only mask (hot path: no sliding window).
264	template <int CN = CTA_N>
265	__device__ __forceinline__ void pf_mask(float (&s)[CN/2], int col0, int qlo, int qhi, int seqlen_k, int causal, int tg) {
266	    // Fast-out for fully-visible tiles (the common case in causal prefill: only the diagonal tile of
267	    // each work item is partially masked, every interior tile is entirely below the diagonal and within
268	    // seqlen_k). kmax = col0+CN-1 is the largest key index this CTA's tile spans; if it is < seqlen_k and
269	    // <= the smaller query position (qlo), no element of either row is masked -> skip the per-element ALU
270	    // that otherwise sits on the QK->next-QK critical path (stealing tensor-pipe issue slots while PV is
271	    // in flight). Conservative (tile-global kmax) so the branch is uniform across the warpgroup.
272	    const int kmax = col0 + CN - 1;
273	    if (kmax < seqlen_k && (!causal || kmax <= qlo)) return;
274	#pragma unroll
275	    for (int c = 0; c < CN / 8; ++c) {
276	        int k0 = col0 + 8 * c + 2 * tg;
277	        if (k0     >= seqlen_k || (causal && k0     > qlo)) s[c*4+0] = -INFINITY;
278	        if (k0 + 1 >= seqlen_k || (causal && k0 + 1 > qlo)) s[c*4+1] = -INFINITY;
279	        if (k0     >= seqlen_k || (causal && k0     > qhi)) s[c*4+2] = -INFINITY;
280	        if (k0 + 1 >= seqlen_k || (causal && k0 + 1 > qhi)) s[c*4+3] = -INFINITY;
281	    }
282	}
283	// Windowed mask (sliding window): valid <=> key<seqlen_k && !(causal&&key>qpos) &&
284	//   !(win_l>=0&&key<qpos-win_l) && !(win_r>=0&&key>qpos+win_r). Collapsed into a per-row valid key
285	// range [lo, hi] (inclusive) computed ONCE, then 2 comparisons/element instead of 4 conditions/element.
286	// The mask sits on the critical path between the QK wgmma result and the next wgmma issue, so halving
287	// its ALU recovers tensor-pipe utilization that softcap/SWA otherwise lose (NCU: tensor 23%->~).
288	template <int CN = CTA_N>
289	__device__ __forceinline__ void pf_mask_win(float (&s)[CN/2], int col0, int qlo, int qhi, int seqlen_k,
290	                                            int causal, int win_l, int win_r, int tg, int lpad = 0) {
291	    constexpr int NEG = -0x40000000;                                  // -inf sentinel for "no left bound"
292	    int lo0 = (win_l >= 0) ? (qlo - win_l) : NEG;
293	    int lo1 = (win_l >= 0) ? (qhi - win_l) : NEG;
294	    // cache_leftpad: keys [0, lpad) are ignored -> absolute lower bound on the valid key range (folds in
295	    // alongside the relative sliding-window left bound; lpad==0 leaves lo0/lo1 untouched, zero overhead).
296	    if (lpad > 0) { if (lpad > lo0) lo0 = lpad; if (lpad > lo1) lo1 = lpad; }
297	    int hi0 = seqlen_k - 1, hi1 = seqlen_k - 1;                       // upper bound folds in seqlen_k
298	    if (causal)     { if (qlo < hi0) hi0 = qlo;        if (qhi < hi1) hi1 = qhi; }
299	    if (win_r >= 0) { int t = qlo + win_r; if (t < hi0) hi0 = t;  t = qhi + win_r; if (t < hi1) hi1 = t; }
300	    // Fast-out for fully-visible tiles (same lever as pf_mask): if every key index this tile spans lies
301	    // within the most-restrictive [lo,hi] of both rows, nothing is masked -> skip the per-element ALU on
302	    // the QK->next-QK critical path. lo = max(lo0,lo1) (tightest left), hi = min(hi0,hi1) (tightest right).
303	    const int kmax = col0 + CN - 1;
304	    const int lo = lo0 > lo1 ? lo0 : lo1, hi = hi0 < hi1 ? hi0 : hi1;
305	    if (col0 >= lo && kmax <= hi) return;
306	#pragma unroll
307	    for (int c = 0; c < CN / 8; ++c) {
308	        int k0 = col0 + 8 * c + 2 * tg;
309	        if (k0     < lo0 || k0     > hi0) s[c*4+0] = -INFINITY;
310	        if (k0 + 1 < lo0 || k0 + 1 > hi0) s[c*4+1] = -INFINITY;
311	        if (k0     < lo1 || k0     > hi1) s[c*4+2] = -INFINITY;
312	        if (k0 + 1 < lo1 || k0 + 1 > hi1) s[c*4+3] = -INFINITY;
313	    }
314	}
315	// Hardware tanh approximation (matches cutlass::fast_tanh / FA3's softcap path): a single SFU
316	// instruction vs the ~20-instruction libdevice tanhf -- softcap feeds exp2 so approx is ample.
317	__device__ __forceinline__ float fast_tanh(float x) {
318	    float r; asm("tanh.approx.f32 %0, %1;" : "=f"(r) : "f"(x)); return r;
319	}
320	// Logit softcap, applied to the RAW Q.K^T before masking. softmax_stats later multiplies by `scale`,
321	// so store softcap*tanh(raw*scale/softcap)/scale to get an effective logit of softcap*tanh(raw*scale/softcap).
322	template <int CN = CTA_N>
323	__device__ __forceinline__ void pf_softcap(float (&s)[CN/2], float scale, float softcap) {
324	    const float a = scale / softcap;       // raw -> tanh argument
325	    const float b = softcap / scale;       // tanh -> stored value (softmax_stats re-applies *scale)
326	#pragma unroll
327	    for (int i = 0; i < CN / 2; ++i) s[i] = fast_tanh(s[i] * a) * b;
328	}
