465	                "wgmma.mma_async.sync.aligned.m64n48k16.f32.f16.f16 " PF_ACC24 ",%24,%25,p,%27,%28,%29,%30;\n}\n"
466	                : PF_OUT24(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
467	            else
