469	                "wgmma.mma_async.sync.aligned.m64n48k16.f32.bf16.bf16 " PF_ACC24 ",%24,%25,p,%27,%28,%29,%30;\n}\n"
470	                : PF_OUT24(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
471	        } else if constexpr (CN == 64) {
