478	                "wgmma.mma_async.sync.aligned.m64n64k16.f32.bf16.bf16 " PF_ACC32 ",%32,%33,p,%35,%36,%37,%38;\n}\n"
479	                : PF_OUT32(s, 0) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
480	        } else if constexpr (CN == 80) {
