511	// One 64-col output box: (CN/16)x m64n64k16 wgmma accumulating into acc[O..O+31] (O compile-time).
512	template <typename T, int O, int N, int CN>
513	__device__ __forceinline__ void pv_box64(float (&acc)[N], const uint32_t (&P)[CN/4], uint64_t baseV) {
514	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
515	#pragma unroll
516	    for (int kb = 0; kb < CN / 16; ++kb) {
517	        uint64_t dB = desc_add(baseV, (uint32_t)v_doff(kb));
518	        if constexpr (is_f16<T>())
519	            asm volatile(
520	            "{\n.reg .pred p;\n setp.ne.b32 p, %37, 0;\n"
521	            "wgmma.mma_async.sync.aligned.m64n64k16.f32.f16.f16 " PF_ACC32 ",{%32,%33,%34,%35},%36,p,%38,%39,%40;\n}\n"
522	            : PF_OUT32(acc, O)
523	            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
524	        else
525	            asm volatile(
526	            "{\n.reg .pred p;\n setp.ne.b32 p, %37, 0;\n"
527	            "wgmma.mma_async.sync.aligned.m64n64k16.f32.bf16.bf16 " PF_ACC32 ",{%32,%33,%34,%35},%36,p,%38,%39,%40;\n}\n"
528	            : PF_OUT32(acc, O)
529	            : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
530	    }
531	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
532	}
533	template <int N>
534	__device__ __forceinline__ void rescale_o_g(float (&acc_o)[N], const float* sc) {
535	#pragma unroll
536	    for (int c = 0; c < N / 4; ++c) {
537	        acc_o[c*4+0] *= sc[0]; acc_o[c*4+1] *= sc[0];
538	        acc_o[c*4+2] *= sc[1]; acc_o[c*4+3] *= sc[1];
539	    }
540	}
541	// PV: emit ceil(HDVsm/64) 64-col boxes. V box b starts CN*64 elems (one CN-row col-block) apart;
542	// the descriptor leading-byte-offset spans that same col-block (CN*64*2 = CN*128 bytes).
543	template <typename T, int HDV, int CN>
544	__device__ __forceinline__ void pv_boxes(float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4], uint32_t sV_base) {
545	    constexpr uint32_t LBO = (uint32_t)(CN * 128), BOX = (uint32_t)(CN * 128);
546	    pv_box64<T, 0, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base, LBO, SW_V_SBO, 1));
547	    if constexpr (HDV >= 128) pv_box64<T, 32, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 1*BOX, LBO, SW_V_SBO, 1));
548	    if constexpr (HDV >= 192) pv_box64<T, 64, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 2*BOX, LBO, SW_V_SBO, 1));
549	    if constexpr (HDV >= 256) pv_box64<T, 96, HDV/2, CN>(acc_o, P, make_smem_desc(sV_base + 3*BOX, LBO, SW_V_SBO, 1));
550	}
551	// First K-block: QK only (s = Q.K^T), HD-generic.
552	template <typename T, int HDt, int CN, int CM = CTA_M>
553	__device__ __forceinline__ void qk_gemm_g(float (&s)[CN/2], uint32_t sQ_wg, uint32_t sK_base) {
554	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
555	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
556	    qk_batch_g<T, HDt, CN, CM>(s, baseA, baseB, 0);
557	    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
558	    wg_fence_c(s);
559	}
560	// Fused QK (next block) + rescale O + PV (current block), HD/HDV/CN-generic. acc_o has HDV/2 regs.
561	template <typename T, int HD, int HDV, int CN, int CM = CTA_M>
562	__device__ __forceinline__ void qk_rs_pv_g(float (&s)[CN/2], float (&acc_o)[HDV/2], const uint32_t (&P)[CN/4],
563	                                           uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base, const float* sc) {
564	    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
565	    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
566	    qk_batch_g<T, HD, CN, CM>(s, baseA, baseB, 0);
567	    rescale_o_g(acc_o, sc);
568	    pv_boxes<T, HDV, CN>(acc_o, P, sV_base);
