650	__device__ __forceinline__ void build_P_rs_fp8(const float (&s)[64], uint32_t (&P16)[16], int tg, int group) {
651	#pragma unroll
652	    for (int c = 0; c < 16; ++c) {
653	        __nv_fp8_e4m3 e0(s[c*4+0]), e1(s[c*4+1]), e2(s[c*4+2]), e3(s[c*4+3]);
654	        P16[c] = (uint32_t)e0.__x | ((uint32_t)e1.__x << 8) | ((uint32_t)e2.__x << 16) | ((uint32_t)e3.__x << 24);
655	    }
