657	    const int sel_up = lane_03 ? 0x5410 : 0x1054, sel_lo = lane_03 ? 0x7632 : 0x3276;
658	    const int up = (tg == 0) ? 0 : (tg == 1) ? 3 : (tg == 2) ? 1 : 2;   // upper_map[tg]
