666	        lower0 = __shfl_sync(0xffffffffu, lower0, src_lo, 32);
667	        P16[2*u + 0] = __byte_perm(upper0, lower0, sel_up);
668	        P16[2*u + 1] = __byte_perm(upper0, lower0, sel_lo);
