#pragma unroll
    for (int c8 = 0; c8 < HDVt / 8; ++c8) {
        int o = voffR<ROWS>(key, c8 * 8);
        if (!valid) { *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0); continue; }
