        if (win_l >= 0) { int lo = (t.row0 / rep) + t.delta - win_l; if (lo > 0) n_beg = lo / CN; }
        if (!causal && win_r >= 0) { int tt = (qabs_max + win_r) / CN + 1; if (tt < n_max) n_max = tt; }
