2690	// Decode via the prefill wgmma mainloop + split-KV (bf16, hd==hdv in {64,128}, no softcap/SWA).
2691	// Allocates per-split scratch (normalized O + lse), launches prefill_kernel with grid.x = num_splits,
2692	// then dec::combine_kernel reduces across splits. num_splits auto-fills ~2 waves of CTAs, capped by
2693	// n_max (key tiles) so no split is wasted; LSEpart is pre-filled -inf so empty/early-out splits drop.
2694	// Largest stage count in [1,DS_MAX_STAGES] whose Q + STAGES*(K+V) smem fits the Hopper dynamic-smem cap
2695	// (~227KB), for a CN-wide key tile and HDsm/HDVsm-padded head dims (TC is 16-bit here). Decode uses a
2696	// single consumer WG (cm=64) so Q smem halves -> deeper K/V pipelines fit, hiding more load latency.
2697	static constexpr int DS_MAX_STAGES = 5;
2698	// occ = target CTAs/SM: occ=2 halves the smem budget so two CTAs co-reside (2x memory-level
2699	// parallelism for DRAM-latency-bound decode). Returns the deepest pipeline that fits.
2700	static constexpr int ds_fit_stages(int cn, int hdsm, int hdvsm, int cm = pf::CTA_M, int occ = 1) {
2701	    const int per = (cn * hdsm + cn * hdvsm) * 2;
2702	    const int qb  = cm * hdsm * 2;
2703	    const int budget = (227 * 1024 - 64) / occ;
2704	    int s = DS_MAX_STAGES;
2705	    while (s > 1 && qb + s * per > budget) --s;
2706	    return s;
2707	}
2708	
2709	template <typename TIn, typename TC, int HD, int HDV>
2710	static void launch_decode_split(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2711	                                at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2712	                                const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2713	                                const std::optional<at::Tensor>& page_table,
2714	                                const std::optional<at::Tensor>& qd_, const std::optional<at::Tensor>& kd_,
2715	                                const std::optional<at::Tensor>& vd_,
2716	                                int b, int hq, int hkv, int total_q, int max_q, int max_klen, int cfg_splits,
2717	                                double scale, bool causal, double softcap, int win_l, int win_r,
2718	                                const int* leftpad_k, cudaStream_t stream) {
2719	    using namespace pf;
2720	    const bool paged = page_table.has_value();
2721	    int rep = hq / hkv;
2722	    long q_row = q.stride(0), q_head = q.stride(1);
2723	    long k_row, k_head, v_row, v_head;
2724	    if (paged) { k_row = k.stride(1); k_head = k.stride(2); v_row = v.stride(1); v_head = v.stride(2); }
2725	    else       { k_row = k.stride(0); k_head = k.stride(1); v_row = v.stride(0); v_head = v.stride(1); }
2726	    long o_row = out.stride(0), o_head = out.stride(1);
2727	    int block_size = paged ? (int)k.size(1) : 0;
2728	    int page_stride = paged ? (int)page_table->stride(0) : 0;
2729	    const float* qd = qd_ ? (const float*)qd_->data_ptr() : nullptr;
2730	    const float* kd = kd_ ? (const float*)kd_->data_ptr() : nullptr;
2731	    const float* vd = vd_ ? (const float*)vd_->data_ptr() : nullptr;
2732	    int ds_b = qd_ ? (int)qd_->stride(0) : 0, ds_h = qd_ ? (int)qd_->stride(1) : 0;
2733	
2734	    // Key-tile width (DCN) + STAGES, chosen per EFFECTIVE context length. hd128 has two regimes:
2735	    //   wide (DCN=128, STAGES=3): moderate ctx -> wgmma n-width + fewer/meatier splits win;
2736	    //   deep (DCN=64,  STAGES=5): long ctx     -> deeper K/V pipeline hides DRAM latency.
2737	    // Larger head dims are smem-forced narrow (192->64, 256->48) so wide==deep (single instantiation).
2738	    constexpr int DHDsm = ((HD + 63) / 64) * 64, DHDVsm = ((HDV + 63) / 64) * 64;
2739	    // hd256: non-windowed (deep) wants wider CN=64 (fewer/meatier tiles amortize the wasted-M
2740	    // softmax; STAGES=3 still fits smem); windowed+softcap (gemma2, wide) keeps CN=48/STAGES=4
2741	    // (the deeper K/V pipeline hides the extra tanh/mask latency better than wider tiles).
2742	    constexpr int DCN_W = (HD == 256) ? 48 : (HD == 192) ? 64 : CTA_N;   // hd128 -> 128
2743	    constexpr int DCN_D = (HD == 256) ? 64 : (HD == 192) ? 64 : 64;      // hd128 -> 64
2744	    // Deep path occupancy. NCU shows the deep decode is occupancy/latency-bound, NOT bandwidth-bound:
2745	    // ~8% achieved occupancy (1 consumer WG == 4 active warps), DRAM only ~56% peak, top stalls
2746	    // wait(wgmma)+long-scoreboard(loads). Adding warps that do WASTED-M work does not help: a 2nd
2747	    // consumer WG (CM=128) regresses (it computes 64 dead rows that contend for issue slots), and a
2748	    // 2nd CTA (DEEP2) costs pipeline depth on hd128. DEEP2 (2 CTA/SM) is kept ONLY for the compute-
2749	    // heavier HD>=192 small-value decode (diffv: enough real wgmma work to overlap a 2nd CTA).
2750	    // DCM=64 => single consumer warpgroup (decode is tiny-M; a 2nd WG would be fully masked).
2751	    constexpr int DCM = 64;
2752	    constexpr int DST_D2 = ds_fit_stages(DCN_D, DHDsm, DHDVsm, DCM, 2);  // 2 CTA/SM
2753	    constexpr bool DEEP2 = (HDV <= 128) && (HD >= 192) && (DST_D2 >= 2);
2754	    constexpr int DCM_DEEP = DCM, DCM_W = DCM;
2755	    constexpr int DST_D = DEEP2 ? DST_D2 : ds_fit_stages(DCN_D, DHDsm, DHDVsm, DCM, 1);
2756	    constexpr int MINB_D = DEEP2 ? 2 : 1;
2757	    constexpr int DST_W = ds_fit_stages(DCN_W, DHDsm, DHDVsm, DCM);
2758	    // Deep (narrow-CN, STAGES=5) for plain non-windowed hd128 -> hides DRAM latency. Windowed (SWA)
2759	    // hd128 uses the wide path: split-KV over a sliding window leaves the deep pipeline mostly unfilled
2760	    // (few in-window tiles/split), so wider tiles + GPU-filling split count measure better.
2761	    // "deep" = the DRAM-latency-hiding regime (4-wave split target + >=2-tiles/split pipeline-fill
2762	    // guard). hd128 long-ctx gets it via the narrow DCN (DCN_W!=DCN_D); the big head dims (>=192) are
2763	    // ALREADY smem-forced narrow (DCN_W==DCN_D) and run 1 CTA/SM, so they want the same treatment
2764	    // (fill the 4-5 stage K/V pipeline + spread enough CTAs across SMs). Windowed stays wide.
2765	    const bool deep = ((DCN_W != DCN_D) || (HD >= 192)) && (win_l < 0) && (win_r < 0);
2766	    const int DCN = deep ? DCN_D : DCN_W;
2767	    const int DCM_RUN = deep ? DCM_DEEP : DCM_W;
2768	    int tiles_m = (max_q * rep + DCM_RUN - 1) / DCM_RUN;
2769	    // n_max key-tiles (causal: last query attends all keys -> ceil(klen/CN)); cap splits to it.
2770	    int n_max_est = (max_klen + DCN - 1) / DCN;
2771	    int num_splits;
2772	    if (cfg_splits > 0) num_splits = cfg_splits;
2773	    else {
2774	        int dev = 0; cudaGetDevice(&dev);
2775	        int sms = 132; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
2776	        int base = tiles_m * hkv * b;   // resident CTAs (hkv*batch tiles) before splitting
2777	        // Wave-quantization-aware split count. An NCU split sweep across the whole decode family
2778	        // shows the optimum is the LARGEST split count that still fits in ~ONE occupancy wave
2779	        // (base*splits ~ sms*bps): splitting past one wave adds a partial-wave tail (those SMs cost
2780	        // a FULL wave of latency) plus per-split Q-load + combine overhead, which strictly regresses
2781	        // -- e.g. gemma2 0.99@2 -> 0.79@3 -> 0.82@5, blk32 0.98@2 -> 0.80@12. The old 2-4 wave target
2782	        // therefore over-split every shape. bps = co-resident CTAs/SM (DEEP2 packs 2/SM, else 1/SM),
2783	        // so one wave is sms*bps CTAs. n_max_est (below) clamps to available key-tiles.
2784	        int bps = deep ? MINB_D : 1;
2785	        int want = std::max(1, (sms * bps) / (base > 0 ? base : 1));
